:root {
  --color-bg: #1e1e2f;
  --color-surface: #2a2a40;
  --color-primary: #6c5ce7;
  --color-primary-hover: #5a4bd1;
  --color-text: #f5f5f5;
  --color-text-muted: #b0b0c0;
  --color-accent: #00cec9;
  --color-error: #ff6b6b;
  --radius: 12px;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: var(--font);
  font-size: 18px;
  line-height: 1.5;
  background: radial-gradient(circle at 20% 20%, #2a2a40, #1e1e2f 70%);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.card {
  background: var(--color-surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px;
  width: 100%;
  max-width: 520px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
  color: var(--color-accent);
}

.subtitle {
  font-size: 1rem;
  color: var(--color-text-muted);
  margin-bottom: 28px;
}

.field-group {
  margin-bottom: 20px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 1rem;
}

.input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.currency-symbol {
  position: absolute;
  left: 14px;
  color: var(--color-text-muted);
  font-weight: 600;
  pointer-events: none;
}

input[type="number"] {
  width: 100%;
  padding: 14px 14px 14px 34px;
  font-size: 1.1rem;
  font-family: var(--font);
  background: #1e1e2f;
  border: 2px solid #3a3a55;
  border-radius: 8px;
  color: var(--color-text);
  transition: border-color 0.2s, box-shadow 0.2s;
  -moz-appearance: textfield;
}

input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

input[type="number"]:hover {
  border-color: #4a4a6a;
}

input[type="number"]:focus-visible {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.3);
}

.error {
  display: block;
  color: var(--color-error);
  font-size: 0.9rem;
  margin-top: 6px;
  min-height: 1.2em;
}

.btn-calculate {
  width: 100%;
  padding: 16px;
  font-size: 1.1rem;
  font-weight: 700;
  font-family: var(--font);
  color: #fff;
  background: var(--color-primary);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  margin-top: 8px;
}

.btn-calculate:hover {
  background: var(--color-primary-hover);
}

.btn-calculate:focus-visible {
  outline: none;
  box-shadow: 0 0 0 4px rgba(108, 92, 231, 0.5);
}

.btn-calculate:active {
  transform: scale(0.98);
}

.result {
  margin-top: 32px;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.result h2 {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.change-amount {
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--color-accent);
  margin-bottom: 20px;
  letter-spacing: -0.02em;
}

.result h3 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-muted);
  margin-bottom: 12px;
}

.breakdown {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.breakdown li {
  background: #1e1e2f;
  border: 1px solid #3a3a55;
  border-radius: 8px;
  padding: 8px 14px;
  font-size: 1rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 6px;
}

.breakdown .count {
  color: var(--color-accent);
  font-weight: 800;
}

.breakdown .denom {
  color: var(--color-text-muted);
  font-weight: 500;
}

@media (max-width: 480px) {
  body {
    padding: 16px;
  }
  .card {
    padding: 24px 20px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .change-amount {
    font-size: 1.8rem;
  }
}

const DENOMINATIONS = [2000, 1000, 500, 200, 100, 50, 20, 10, 5]; // in cents

function formatCurrency(cents) {
  return '£' + (cents / 100).toFixed(2);
}

function formatDenomination(cents) {
  return cents >= 100 ? '£' + (cents / 100) : (cents) + 'p';
}

function calculateChange(priceCents, paidCents) {
  let change = paidCents - priceCents;
  const breakdown = [];
  for (const denom of DENOMINATIONS) {
    const count = Math.floor(change / denom);
    if (count > 0) {
      breakdown.push({ denom, count });
      change -= count * denom;
    }
  }
  return breakdown;
}

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('change-form');
  const priceInput = document.getElementById('price');
  const paidInput = document.getElementById('paid');
  const priceError = document.getElementById('price-error');
  const paidError = document.getElementById('paid-error');
  const resultSection = document.getElementById('result');
  const changeAmountEl = document.getElementById('change-amount');
  const breakdownList = document.getElementById('breakdown-list');

  function clearErrors() {
    priceError.textContent = '';
    paidError.textContent = '';
    priceInput.removeAttribute('aria-invalid');
    paidInput.removeAttribute('aria-invalid');
  }

  function showError(input, errorEl, message) {
    errorEl.textContent = message;
    input.setAttribute('aria-invalid', 'true');
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    clearErrors();
    resultSection.hidden = true;

    const priceValue = priceInput.value.trim();
    const paidValue = paidInput.value.trim();

    if (priceValue === '') {
      showError(priceInput, priceError, 'Please enter a price.');
      priceInput.focus();
      return;
    }

    if (paidValue === '') {
      showError(paidInput, paidError, 'Please enter the amount paid.');
      paidInput.focus();
      return;
    }

    const price = parseFloat(priceValue);
    const paid = parseFloat(paidValue);

    if (isNaN(price) || price < 0) {
      showError(priceInput, priceError, 'Price must be a valid non-negative number.');
      priceInput.focus();
      return;
    }

    if (isNaN(paid) || paid < 0) {
      showError(paidInput, paidError, 'Amount paid must be a valid non-negative number.');
      paidInput.focus();
      return;
    }

    const priceCents = Math.round(price * 100);
    const paidCents = Math.round(paid * 100);

    if (paidCents < priceCents) {
      showError(paidInput, paidError, 'Amount paid must be at least the price.');
      paidInput.focus();
      return;
    }

    const changeCents = paidCents - priceCents;

    if (changeCents === 0) {
      changeAmountEl.textContent = 'No change due.';
      breakdownList.innerHTML = '';
      resultSection.hidden = false;
      return;
    }

    const breakdown = calculateChange(priceCents, paidCents);

    changeAmountEl.textContent = formatCurrency(changeCents);
    breakdownList.innerHTML = '';
    for (const { denom, count } of breakdown) {
      const li = document.createElement('li');
      const countSpan = document.createElement('span');
      countSpan.className = 'count';
      countSpan.textContent = count + '×';
      const denomSpan = document.createElement('span');
      denomSpan.className = 'denom';
      denomSpan.textContent = formatDenomination(denom);
      li.appendChild(countSpan);
      li.appendChild(denomSpan);
      breakdownList.appendChild(li);
    }

    resultSection.hidden = false;
  });
});
